function getWorldMatrix(object) {
    // Walk up the parent chain and accumulate transforms
    object.updateMatrixWorld(true);
    return object.matrixWorld.clone();
}

function meshToOBJ(mesh) {
    // Ensure world matrix is up to date
    mesh.updateMatrixWorld(true);
    const worldMatrix = mesh.matrixWorld;

    const geo = mesh.geometry;
    const pos = geo.getAttribute('position');
    const normals = geo.getAttribute('normal');
    const index = geo.getIndex();

    let obj = `# ${mesh.name}\n`;

    // Transform vertices to world space
    const v = new THREE.Vector3();
    for (let i = 0; i < pos.count; i++) {
        v.set(pos.getX(i), pos.getY(i), pos.getZ(i));
        v.applyMatrix4(worldMatrix);
        obj += `v ${v.x} ${v.y} ${v.z}\n`;
    }

    // Transform normals to world space (use normal matrix)
    if (normals) {
        const normalMatrix = new THREE.Matrix3().getNormalMatrix(worldMatrix);
        const n = new THREE.Vector3();
        for (let i = 0; i < normals.count; i++) {
            n.set(normals.getX(i), normals.getY(i), normals.getZ(i));
            n.applyMatrix3(normalMatrix).normalize();
            obj += `vn ${n.x} ${n.y} ${n.z}\n`;
        }
    }

    // Faces
    if (index) {
        for (let i = 0; i < index.count; i += 3) {
            const a = index.getX(i) + 1;
            const b = index.getX(i + 1) + 1;
            const c = index.getX(i + 2) + 1;
            if (normals) {
                obj += `f ${a}//${a} ${b}//${b} ${c}//${c}\n`;
            } else {
                obj += `f ${a} ${b} ${c}\n`;
            }
        }
    } else {
        for (let i = 0; i < pos.count; i += 3) {
            const a = i + 1;
            const b = i + 2;
            const c = i + 3;
            if (normals) {
                obj += `f ${a}//${a} ${b}//${b} ${c}//${c}\n`;
            } else {
                obj += `f ${a} ${b} ${c}\n`;
            }
        }
    }

    return obj;
}

function meshToOBJWithOffset(mesh, vertexOffset) {
    mesh.updateMatrixWorld(true);
    const worldMatrix = mesh.matrixWorld;

    const geo = mesh.geometry;
    const pos = geo.getAttribute('position');
    const normals = geo.getAttribute('normal');
    const index = geo.getIndex();

    let obj = `# ${mesh.name}\n`;
    obj += `o ${mesh.name}\n`;

    const v = new THREE.Vector3();
    for (let i = 0; i < pos.count; i++) {
