ensureDir(linksDir);

// Identify parts: direct children of root that are Groups or Meshes
// In this scene, the root "ferris_wheel" has two Group children:
//   - support_structure
//   - wheel_structure
// Each of these is a "part". Inside wheel_structure, cabin_N sub-groups are also parts.

// We'll define "parts" as:
// 1. Each direct Group child of root (support_structure, wheel_structure)
// 2. For wheel_structure, cabin sub-groups are nested parts.
//
// For part_meshes: we save individual mesh OBJ files under each part's folder.
// For links: we save one combined OBJ per part with all its meshes.

// Strategy: walk root's direct children. For each Group child, identify:
//  - Direct mesh children -> belong to this part
//  - Sub-group children -> each is its own part

function processPart(partGroup, partName) {
    const partDir = path.join(partMeshesDir, partName);
    ensureDir(partDir);

    // Collect direct mesh children only (not from sub-groups)
    const directMeshes = [];
    const subGroups = [];

    for (const child of partGroup.children) {
        if (child.isMesh) {
            directMeshes.push(child);
        } else if (child.isGroup) {
            subGroups.push(child);
        }
    }

    // Save individual mesh OBJ files
    for (const mesh of directMeshes) {
        const objContent = meshToOBJ(mesh);
        const filePath = path.join(partDir, `${mesh.name}.obj`);
        fs.writeFileSync(filePath, objContent);
    }

    // Save combined link OBJ (all meshes in this part, including sub-group meshes?
    // No - only direct meshes for this part's link file)
    // Actually, for the link: it should contain all direct meshes of this specific part.
    if (directMeshes.length > 0) {
        let combinedOBJ = `# Combined mesh for part: ${partName}\n`;
        let vertexOffset = 0;
        for (const mesh of directMeshes) {
            const { obj, vertexCount } = meshToOBJWithOffset(mesh, vertexOffset);
            combinedOBJ += obj;
            vertexOffset += vertexCount;
        }
        const linkPath = path.join(linksDir, `${partName}.obj`);
        fs.writeFileSync(linkPath, combinedOBJ);
    }

    // Process sub-groups as separate parts
    for (const subGroup of subGroups) {
        processPart(subGroup, subGroup.name);
    }
}

// Process top-level parts
for (const child of root.children) {
    if (child.isGroup) {
        processPart(child, child.name);
    } else if (child.isMesh) {
        // Direct mesh under root - treat as its own part
        const partName = child.name;
        const partDir = path.join(partMeshesDir, partName);
        ensureDir(partDir);
        const objContent = meshToOBJ(child);
        fs.writeFileSync(path.join(partDir, `${child.name}.obj`), objContent);
        fs.writeFileSync(path.join(linksDir, `${partName}.obj`), objContent);
    }
}

// For wheel_structure: direct meshes (hub, rim, spokes) go in wheel_structure folder,
// and cabin sub-groups each get their own folder.
// The link for wheel_structure should only contain its direct meshes (hub, rim, spokes).
// Each cabin_N gets its own link file too.

console.log('Export complete!');

// Print summary
function printTree(dir, prefix = '') {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    entries.sort((a, b) => a.name.localeCompare(b.name));
    for (let i = 0; i < entries.length; i++) {
        const entry = entries[i];
        const isLast = i === entries.length - 1;
        const connector = isLast ? '└── ' : '├── ';
        console.log(`${prefix}${connector}${entry.name}`);
        if (entry.isDirectory()) {
            const newPrefix = prefix + (isLast ? '    ' : '│   ');
            printTree(path.join(dir, entry.name), newPrefix);
        }
    }
}

console.log('\nOutput structure:');
console.log('output/');
printTree(outputBase);

